CREATE TABLE IF NOT EXISTS negocios (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(150) NOT NULL, tipo VARCHAR(150) NOT NULL, color VARCHAR(30) NOT NULL, descripcion VARCHAR(500) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS usuarios (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, pass VARCHAR(255) NOT NULL, rol VARCHAR(20) NOT NULL, negocio_id INT UNSIGNED NULL, estado VARCHAR(20) NOT NULL DEFAULT 'Activo', CONSTRAINT fk_usuarios_negocio FOREIGN KEY (negocio_id) REFERENCES negocios(id) ON DELETE SET NULL, INDEX idx_usuarios_negocio (negocio_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS productos (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, negocio_id INT UNSIGNED NOT NULL, nombre VARCHAR(190) NOT NULL, precio DECIMAL(12,2) NOT NULL, stock INT UNSIGNED NOT NULL, minimo INT UNSIGNED NOT NULL DEFAULT 0, CONSTRAINT fk_productos_negocio FOREIGN KEY (negocio_id) REFERENCES negocios(id) ON DELETE RESTRICT, INDEX idx_productos_negocio_nombre (negocio_id,nombre)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ventas (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, negocio_id INT UNSIGNED NOT NULL, producto_id INT UNSIGNED NOT NULL, usuario_id INT UNSIGNED NOT NULL, cliente_id INT UNSIGNED NULL, cantidad INT UNSIGNED NOT NULL, total DECIMAL(12,2) NOT NULL, fecha DATETIME NOT NULL, CONSTRAINT fk_ventas_negocio FOREIGN KEY (negocio_id) REFERENCES negocios(id) ON DELETE RESTRICT, CONSTRAINT fk_ventas_producto FOREIGN KEY (producto_id) REFERENCES productos(id) ON DELETE RESTRICT, CONSTRAINT fk_ventas_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE RESTRICT, CONSTRAINT fk_ventas_cliente FOREIGN KEY (cliente_id) REFERENCES usuarios(id) ON DELETE SET NULL, INDEX idx_ventas_negocio_fecha (negocio_id,fecha), INDEX idx_ventas_cliente_fecha (cliente_id,fecha)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS turnos (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, cliente_id INT UNSIGNED NOT NULL, negocio_id INT UNSIGNED NOT NULL, profesional VARCHAR(150) NOT NULL, fecha DATETIME NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'Pendiente', CONSTRAINT fk_turnos_cliente FOREIGN KEY (cliente_id) REFERENCES usuarios(id) ON DELETE RESTRICT, CONSTRAINT fk_turnos_negocio FOREIGN KEY (negocio_id) REFERENCES negocios(id) ON DELETE RESTRICT, INDEX idx_turnos_cliente_fecha (cliente_id,fecha), INDEX idx_turnos_negocio_fecha (negocio_id,fecha)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS lux_schema_version (version INT UNSIGNED NOT NULL PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
